-- Trainer app — push notifications when a rest timer ends (run once in Supabase → SQL Editor).
-- No secrets in this file. Afterwards run supabase/push_secrets.local.sql (generated by tools/make-vapid.js).

create extension if not exists pg_cron;
create extension if not exists pg_net;

-- One row per device that allowed notifications.
create table if not exists public.push_subscriptions (
  id         bigint generated always as identity primary key,
  user_id    uuid        not null references auth.users (id) on delete cascade,
  endpoint   text        not null unique,
  p256dh     text        not null,
  auth       text        not null,
  created_at timestamptz not null default now()
);
alter table public.push_subscriptions enable row level security;
create policy "own subs: select" on public.push_subscriptions for select using (auth.uid() = user_id);
create policy "own subs: insert" on public.push_subscriptions for insert with check (auth.uid() = user_id);
create policy "own subs: update" on public.push_subscriptions for update using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "own subs: delete" on public.push_subscriptions for delete using (auth.uid() = user_id);

-- The currently running rest timer (at most one per user). The app upserts/deletes it.
create table if not exists public.rest_timers (
  user_id    uuid        primary key references auth.users (id) on delete cascade,
  fire_at    timestamptz not null,
  title      text        not null,
  body       text        not null,
  updated_at timestamptz not null default now()
);
alter table public.rest_timers enable row level security;
create policy "own timer: select" on public.rest_timers for select using (auth.uid() = user_id);
create policy "own timer: insert" on public.rest_timers for insert with check (auth.uid() = user_id);
create policy "own timer: update" on public.rest_timers for update using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "own timer: delete" on public.rest_timers for delete using (auth.uid() = user_id);
create index if not exists rest_timers_fire_at on public.rest_timers (fire_at);

-- Every 5 seconds: only when a timer is due, call the Edge Function (URL + secret come from Vault).
select cron.schedule(
  'trainer-rest-push',
  '5 seconds',
  $$
  select net.http_post(
    url     := (select decrypted_secret from vault.decrypted_secrets where name = 'rest_push_url'),
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-cron-secret', (select decrypted_secret from vault.decrypted_secrets where name = 'rest_push_secret')
    ),
    body    := '{}'::jsonb
  )
  where exists (select 1 from public.rest_timers where fire_at <= now());
  $$
);
